import React, { useEffect, useRef, useState } from "react";
import "../App.css";
import botIcon from "../bot-icon.png";
import "./ChatBox.css";

const ChatBox = ({ messages, setMessages, setLatestQuery }) => {
  const [input, setInput] = useState("");
  const messagesEndRef = useRef(null);

  // 🔹 Scroll to bottom when messages update
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSendMessage = async () => {
    if (input.trim() === "") return;

    const newMessages = [...messages, { text: input, type: "user" }];
    setMessages(newMessages); // ✅ Update global messages
    setLatestQuery(input); // ✅ Save latest query for YouTube/Wikipedia
    setInput("");

    try {
      const response = await fetch("http://localhost:5000/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prompt: input }),
      });

      const data = await response.json();

      if (response.ok) {
        setMessages((prevMessages) => [
          ...prevMessages,
          { text: data.response, type: "bot" },
        ]);
      } else {
        throw new Error(data.error || "AI response failed");
      }
    } catch (error) {
      console.error("Error fetching response:", error);
      setMessages((prevMessages) => [
        ...prevMessages,
        { text: "⚠️ AI is not responding. Try again later.", type: "bot" },
      ]);
    }
  };

  // ✅ Function to render messages properly (handles code blocks)
  const renderMessage = (text) => {
    if (text.includes("```")) {
      const codeMatch = text.match(/```(?:\w+)?\s*([\s\S]*?)```/);
      if (codeMatch) {
        return (
          <pre className="code-block">
            <code>{codeMatch[1]}</code>
          </pre>
        );
      }
    }
    return <p>{text}</p>;
  };

  return (
    <div className="chatbox">
      <div className="messages">
        {messages.map((msg, index) => (
          <div key={index} className={`message-container ${msg.type}`}>
            {msg.type === "bot" && <img src={botIcon} alt="Bot" className="bot-icon" />}
            <div className={`message ${msg.type}`}>{renderMessage(msg.text)}</div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>
      <div className="input-area">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Ask me anything..."
        />
        <button onClick={handleSendMessage}>➤</button>
      </div>
    </div>
  );
};

export default ChatBox;
